steps.action:
curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { cycles(first: 50, orderBy: name) { nodes { id name startDate endDate team { name } } } users(first: 50, query: \"Priya Nair\") { nodes { id name } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { cycles(first: 50) { nodes { id name startsAt endsAt team { name } } } users(first: 100) { nodes { id name email } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { 
      mobIssues: issues(cycleId: \"c-mob-14\", first: 50) { 
        nodes { id title priority assignee { name } } 
      }
      webIssues: issues(cycleId: \"c-web-14\", first: 50) { 
        nodes { id title priority assignee { name } } 
      }
    }"
  }'
